// 添加 / 编辑求职期望（/intentions/new，编辑态 /intentions/:id）——
// 2026-08-21 按用户截图重写：推翻 08-19 的「一句话填空词元」版，回到朴素的 label + 值 清单表单。
//
// 版式（见 docs/design/添加求职期望规格.md「主屏」一节）自上而下：
//   返回栏 ‹（无标题、无右键）→ 大标题 + 副标题 → 六行条目 → 底部固定按钮。
//   每行 = 小字灰 label + 大字值行（未填时灰占位）+ 右侧 ›，行间一条细分隔线；
//   第 1 行「求职类型」例外：行内两个单选圆点右对齐，没有值行也没有 ›。
//
// 数据来源只有一处 —— 全局 意向草稿，不在本页留 useState 副本。
//   工作城市 / 期望职位 / 感兴趣城市 / 期望行业 四项要跳次级页，跳走再回来本页会重新挂载，
//   本地 state 那一份必然被清空；薪资走弹层虽然不跳页，为了不出现两份真相也一样写草稿。
//
// 2026-08-22 产品负责人「本意向底线删掉吧，感觉没啥用」：连同「仅AI代理可见 · 触线即拒」
//   徽标与底线滚轮弹层一起摘掉，表单从七行回到六行。
//   删的只是「期望区间」之外那条更硬的底线字段 —— 薪资区间的下限仍然承担底线作用，
//   代理之间依旧只交换「有没有交集」、不交换数字，双盲机制没有因为这次删除而改变。

import { useEffect, useRef, useState } from 'react';
import { useNavigationType, useParams } from 'react-router-dom';
import 数字滚轮层 from '../组件/数字滚轮层';
import 年月滚轮层 from '../组件/年月滚轮层';
import { 校验预计毕业时间 } from '../流程/onboarding配置';
import 样式 from './添加意向.module.css';
// 2026-08-24 全站选择风格统一（C1 定稿）：求职类型改选钮片后不再用 单选点
import { 次级页外壳, 返回栏, 页面大标题, 滚动区, 主按钮 } from '../组件/通用';
import 薪资区间层 from '../组件/薪资区间层';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { use应用状态, type 意向草稿型 } from '../状态/应用状态';
import { 轻提示 } from '../组件/轻提示';
import { 取后端错误文案 } from '../数据/HTTP客户端';

/** 感兴趣城市上限（规格：其他感兴趣城市（N/9））。这里只用于渲染 label 里的计数，
 *  真正的选择上限由次级页 选择城市 把关 —— 上限判断放在能拦住点击的那一层才有意义。 */
const 感兴趣城市上限 = 9;

// 求职侧实习离散档（picker 统一 Task 2）：与学生分流同表，只开放产品定的档位，
// 不用 min/max 生成岗位侧未开放的档；发布岗仍是同组件的连续 1-24 / 1-7。
const 实习月数档 = [1, 3, 6] as const;
const 每周到岗档 = [2, 3, 4, 5] as const;

/**
 * 一行表单条目：小字灰 label + 大字值行 + 右侧 ›。
 * 「有值 / 未填」在版式上唯一的区别就是值行的颜色：未填走 .值占位 的灰，
 * 位置、字号、行高都不变，这样六行的基线不会因为填没填而参差。
 */
function 期望行({
  标签,
  值,
  占位,
  按下,
}: {
  标签: string;
  /** 已填的值；空串 = 未填，此时显示 占位 */
  值: string;
  占位: string;
  按下: () => void;
}) {
  const 有值 = 值 !== '';
  return (
    <button type="button" className={`${样式.条目} 可点`} onClick={按下}>
      {/* 标签外面这层 flex 行是版式的一部分：它把小字标签的行高锁在自己的行盒里，
          去掉之后标签会退回按钮那档更大的行高，六行的基线整体往下掉 */}
      <span className={样式.条目标签行}>
        <span className={样式.条目标签}>{标签}</span>
      </span>
      <span className={样式.条目值行}>
        <span className={`${样式.条目值} ${有值 ? '' : 样式.值占位} 单行`}>
          {有值 ? 值 : 占位}
        </span>
        <span className={样式.尖括号}>›</span>
      </span>
    </button>
  );
}

/**
 * E0：路由 wrapper —— 只解析 ID、读取 Context 并判定编辑目标，不承载表单 hooks。
 * Backend 下有路由 ID 但 后端意向服务端 里不是 active（旧链接/已归档/跨主体）时
 * 终局退场：不派发 开意向草稿（reducer 未命中会返回空草稿、保存就走 create），
 * 新建只来自 /intentions/new。表单 hooks 全在 keyed 子组件 意向编辑表单 里。
 */
export default function 添加意向() {
  const { id: 路由编号 } = useParams<{ id: string }>();
  const { 状态, 数据源模式 } = use应用状态();
  const { 跳转 } = use导航();

  const 有后端目标 = 路由编号 !== undefined
    && 状态.后端意向服务端?.[路由编号]?.status === 'active';
  const 无效后端编辑 = 数据源模式 === 'backend' && 路由编号 !== undefined && !有后端目标;

  if (无效后端编辑) return <意向不可编辑 返回管理={() => 跳转(路径.求职意向管理)} />;
  return <意向编辑表单 key={路由编号 ?? 'new'} 路由编号={路由编号} />;
}

/** E0：Backend 无效编辑坐标的终局退场页 —— 纯展示，不调用 hooks */
function 意向不可编辑({ 返回管理 }: { 返回管理: () => void }) {
  return (
    <次级页外壳 白底>
      <返回栏 返回={返回管理} />
      <页面大标题 标题="编辑求职期望" 说明="这条求职意向不存在或已不可编辑" />
      <主按钮 文字="返回求职意向管理" 按下={返回管理} 禁用={false} />
    </次级页外壳>
  );
}

function 意向编辑表单({ 路由编号 }: { 路由编号?: string }) {
  const { 跳转, 返回 } = use导航();
  const { 状态: 全局, 派发, 操作 } = use应用状态();
  const 导航类型 = useNavigationType();

  const 草稿 = 全局.意向草稿;
  // 编辑态只看 URL 有没有带编号：底部按钮是一键还是两键由它决定，
  // 不依赖草稿里的 编辑编号（草稿要等下面那个 effect 跑完才有值）
  const 编辑态 = 路由编号 !== undefined;

  // 底线弹层删掉之后，本页只剩薪资一个底部弹层，开关用一个布尔就够，不再需要「弹层名」联合类型
  const [薪资层开, 设薪资层开] = useState(false);
  // 实习数值抽屉（picker 统一 Task 2）：页内只记打开哪个字段，临时值由
  // 数字滚轮层 自己持有；确定才经 改草稿 回填，打开 / 取消零写入。
  const [实习轮, 设实习轮] = useState<'月数' | '天数' | null>(null);
  // 预计毕业年月抽屉（picker 统一 Task 3）：父页只持有是否打开，临时值由
  // 年月滚轮层 自己持有；确定才经 改草稿 回填，取消不调用。
  const [毕业轮开, 设毕业轮开] = useState(false);
  const 薪资周期 = 草稿.薪资周期 ?? (草稿.求职类型 === '实习生' ? 'day' : 'month');
  const 薪资单位 = 薪资周期 === 'day' ? ' 元/天' : 薪资周期 === 'hour' ? ' 元/时' : 'K';

  // 办公方式必填校验的可见状态：只在点保存且没选时点亮（aria-invalid + aria-description），
  // 用户点任一办公方式选钮立即熄灭 —— 错误跟着「最后一次校验」走，不常驻。
  // 校验错误不是草稿的一部分，所以不放全局状态，本页局部 state 足够。
  const [办公方式错误, 设办公方式错误] = useState(false);
  const 办公方式组引用 = useRef<HTMLDivElement>(null);

  // 换一条意向（新建 ↔ 编辑互跳）时上一次的错误不该带到新表单上
  useEffect(() => {
    设办公方式错误(false);
  }, [路由编号]);

  // 挂载这一刻草稿装的是哪一条。用 useState 的初值锁住，之后草稿被本页和次级页改也不跟着变 ——
  // 下面那个 effect 要的正是「进来时」的快照，不是「此刻」的值。
  const [挂载时草稿编号] = useState(草稿.编辑编号);

  // 进页面开一份草稿：新建 → 空表；编辑 → 从 求职意向表 里那一条拆回来预填。
  //
  // 坑在这里：本屏跳去次级页（选城市 / 选职位 / 选行业）再 返回() 时会**重新挂载**，
  // 而那一次挂载草稿里正装着用户刚选好的东西，无脑再开一次就全清了（实测：选完城市返回，
  // 工作城市又变回「请选择工作城市」）。所以按导航类型分流：
  //   PUSH / REPLACE = 从意向管理页新进来的一次编辑会话 → 开新草稿；
  //   POP            = 从次级页返回或浏览器后退 → 草稿是自己的，原样留着。
  // 唯一要给 POP 破例的是「直接刷新 /intentions/:id」：那也是 POP，但草稿是空的、
  // 装的不是这一条，不开就永远是空表 —— 所以再加一道「草稿不是本条」的判断。
  useEffect(() => {
    const 草稿不是本条 = 挂载时草稿编号 !== (路由编号 ?? null);
    if (导航类型 !== 'POP' || 草稿不是本条) {
      派发({ 型: '开意向草稿', 编号: 路由编号 ?? null });
    }
  }, [派发, 导航类型, 路由编号, 挂载时草稿编号]);

  /** 本页所有字段改动的单点出口 */
  const 改草稿 = (补丁: Partial<意向草稿型>) => 派发({ 型: '改意向草稿', 补丁 });

  // 薪资回填格式（规格弹层 C）：下限 === 上限 → 「10K」；否则 「10-11K」
  const 薪资文本 =
    草稿.薪资下限 === null || 草稿.薪资上限 === null
      ? ''
      : 草稿.薪资下限 === 草稿.薪资上限
        ? `${草稿.薪资下限}${薪资单位}`
        : `${草稿.薪资下限}-${草稿.薪资上限}${薪资单位}`;
  const 感兴趣城市文本 = 草稿.感兴趣城市们.join('、');
  const 期望行业文本 = 草稿.期望行业们.join('、');

  // 毕业年月抽屉年表（picker 统一 Task 3）：未来 8 年 + 已有毕业年补入，升序去重；
  // 上下界取表头 1 月到表尾 12 月 —— 不用组件「最晚本月」的默认上界，未来值不被夹掉；
  // 缺值临时落「次年 6 月」，只作抽屉初值
  const 毕业初值 = 草稿.毕业时间 || `${new Date().getFullYear() + 1}-06`;
  const 毕业年表 = [...new Set([
    Number(毕业初值.slice(0, 4)),
    ...Array.from({ length: 8 }, (_, 序) => new Date().getFullYear() + 序),
  ])].sort((甲, 乙) => 甲 - 乙);

  // 保存键不再因缺字段置灰（置灰让「为什么不让我存」变成哑谜），改成点保存时按序校验：
  //   工作城市 → 期望职位 → 办公方式，缺哪条轻提示哪条，一条没过就停。
  // 城市和职位是标题「[城市] 职位」的两个组成部分，缺一条就会存出「[] 」这种空壳标题，
  // 意向管理页那一行会变成一片空白且再也点不明白 —— 所以这三项都必须有。
  // 办公方式没选时还要把那一组滚进视口、聚焦第一个选钮，并挂 aria-invalid 提示屏幕阅读器。
  const 校验必填 = (): boolean => {
    if (草稿.工作城市 === '') {
      轻提示('请选择工作城市');
      return false;
    }
    if (草稿.期望职位 === '') {
      轻提示('请选择期望职位');
      return false;
    }
    if (草稿.办公方式.length === 0) {
      设办公方式错误(true);
      轻提示('请选择办公方式');
      const 组 = 办公方式组引用.current;
      组?.scrollIntoView({ block: 'center' });
      组?.querySelector<HTMLButtonElement>('button')?.focus();
      return false;
    }
    if (草稿.求职类型 === '校园招聘') {
      const 错误 = 校验预计毕业时间(草稿.毕业时间 ?? undefined);
      // 已保存的毕业月自然过期不妨碍无关字段编辑；用户改过则按现有规则校验。
      const 原月 = 全局.后端意向服务端?.[草稿.编辑编号 ?? '']?.graduation_month;
      if (错误 && !(编辑态 && 草稿.毕业时间 && 草稿.毕业时间 === 原月)) { 轻提示(错误); return false; }
    }
    if (草稿.求职类型 === '实习生' && (!草稿.实习月数 || !草稿.每周到岗天数)) {
      轻提示('请选择实习月数和每周到岗天数'); return false;
    }
    return true;
  };

  const 提交 = async () => {
    if (!校验必填()) return;
    try {
      await 操作.保存意向(草稿);
      派发({ 型: '清意向草稿' });
      返回();
    } catch (error) {
      轻提示(取后端错误文案(error));
    }
  };

  const 删除 = async () => {
    if (草稿.编辑编号) {
      try {
        await 操作.删除意向(草稿.编辑编号);
        派发({ 型: '清意向草稿' });
        返回();
      } catch (error) {
        轻提示(取后端错误文案(error));
      }
    }
  };

  // ‹ 退出：不保存就走，草稿要归零。这样「保存 / 删除 / 返回」三条出口一致，
  // 下次新建进来必然是干净的空表，不会看见上一轮没存的残留。
  const 退出 = () => {
    派发({ 型: '清意向草稿' });
    返回();
  };

  return (
    /* 2026-08-24 全站选择风格统一（C1 定稿）：页底加白底 */
    <次级页外壳 白底>
      <滚动区 样式覆盖={{ padding: '6px 22px 10px' }}>
        <div className={样式.滚动页首}>
          <返回栏 返回={退出} />
          <页面大标题 标题={编辑态 ? '编辑求职期望' : '添加求职期望'} />
        </div>
        {/* 第 1 行：求职类型 —— 两个选钮片行内右对齐，没有值行也没有 › */}
        {/* 2026-08-24 全站选择风格统一（C1 定稿）：单选圆点改定稿选钮片，选中对勾由 CSS ::before 画 */}
        <div className={`${样式.类型行} ${样式.求职类型区}`}>
          <span className={样式.类型标}>求职类型</span>
          <div className={样式.类型组}>
            {(['全职', '校园招聘', '实习生', '兼职'] as const).map((类型) => {
              const 选中 = 草稿.求职类型 === 类型;
              return (
                <button
                  key={类型}
                  type="button"
                  className={`${样式.类型选项} ${选中 ? 样式.类型选项选中 : ''} 可点`}
                  onClick={() => 改草稿({ 求职类型: 类型 })}
                  aria-pressed={选中}
                >
                  {类型 === '全职' ? '社招全职' : 类型}
                </button>
              );
            })}
          </div>
        </div>

        {草稿.求职类型 === '校园招聘' && <期望行 标签="预计毕业年月" 值={草稿.毕业时间 ?? ''} 占位="请选择毕业年月" 按下={() => 设毕业轮开(true)} />}
        {/* 实习数值改共用数字抽屉（picker 统一 Task 2）：原标签片改两行 期望行，
            与 学生分流 / 发布岗 同一个 数字滚轮层；未填走 请选择 占位，
            确定才回填，打开 / 取消零写入（必填检查照旧拦得住） */}
        {草稿.求职类型 === '实习生' && <期望行 标签="实习时长" 值={草稿.实习月数 ? `至少 ${草稿.实习月数} 个月` : ''} 占位="请选择" 按下={() => 设实习轮('月数')} />}
        {草稿.求职类型 === '实习生' && <期望行 标签="每周到岗" 值={草稿.每周到岗天数 ? `每周 ${草稿.每周到岗天数} 天` : ''} 占位="请选择" 按下={() => 设实习轮('天数')} />}

        {/* 办公方式：复用 求职类型 的选钮片行样式，多选（现场/混合/远程）。
            Task 6 新增必填草稿字段：保存时映射为 BFF wire code，空数组时 映射办公方式 抛错，
            这里在 校验必填 里提前挡住，给 轻提示 而不是让映射层抛。
            语义只挂在这一组上：role=group + aria-label 让读屏软件把它念成一个可命名分组，
            校验没过时 aria-invalid / aria-description 指到组上（不建新元素、不动版式）。 */}
        <div className={样式.类型行}>
          <span className={样式.类型标}>办公方式</span>
          <div
            ref={办公方式组引用}
            className={样式.类型组}
            role="group"
            aria-label="办公方式"
            // oxlint-disable-next-line role-supports-aria-props —— aria-invalid 是全局属性，挂组合法，规则元数据滞后
            aria-invalid={办公方式错误 || undefined}
            // oxlint-disable-next-line role-supports-aria-props —— aria-description 是全局属性，挂组合法，规则元数据滞后
            aria-description={办公方式错误 ? '请选择办公方式' : undefined}
          >
            {(['现场', '混合', '远程'] as const).map((方式) => {
              const 选中 = 草稿.办公方式.includes(方式);
              return (
                <button
                  key={方式}
                  type="button"
                  className={`${样式.类型选项} ${选中 ? 样式.类型选项选中 : ''} 可点`}
                  onClick={() => {
                    // 用户已经开始处理这一组了，校验错误立刻熄灭，再派发原有的选择
                    设办公方式错误(false);
                    改草稿({
                      办公方式: 选中
                        ? 草稿.办公方式.filter((项) => 项 !== 方式)
                        : [...草稿.办公方式, 方式],
                    });
                  }}
                  aria-pressed={选中}
                >
                  {方式}
                </button>
              );
            })}
          </div>
        </div>

        {/* 第 2、3 行跳注册引导里那两屏，带 ?来源=意向 让它们写草稿而不是写 引导预填 */}
        <期望行
          标签="工作城市"
          值={草稿.工作城市}
          占位="请选择工作城市"
          按下={() => 跳转(`${路径.选工作城市}?来源=意向`)}
        />
        <期望行
          标签="期望职位"
          值={草稿.期望职位}
          占位="请选择期望职位"
          按下={() => 跳转(`${路径.选期望职位}?来源=意向`)}
        />

        {/* 第 4 行的 label 自带 N/9 计数（规格表原样），值是顿号连接的城市们 */}
        <期望行
          标签={`其他感兴趣城市（${草稿.感兴趣城市们.length}/${感兴趣城市上限}）`}
          值={感兴趣城市文本}
          占位="请选择更多感兴趣城市"
          按下={() => 跳转(路径.选择城市)}
        />

        {/* 第 5 行开底部弹层，不跳页：薪资是滚轮选数，跳一整屏太重 */}
        <期望行
          标签={`薪资要求（${薪资周期 === 'day' ? '日薪 · 元/天' : 薪资周期 === 'hour' ? '时薪 · 元/时' : '月薪 · K'}）`}
          值={薪资文本}
          占位="请选择薪资要求"
          按下={() => 设薪资层开(true)}
        />

        <期望行
          标签="期望行业"
          值={期望行业文本}
          占位="不限"
          按下={() => 跳转(路径.选期望行业)}
        />
        {/* Task 2：私有筛选要求整段文本区（替代原「哪些情况直接排除？」排除选项卡）——
            草稿.私有偏好 原样作为唯一数据源，onChange 把整段写回草稿；
            不设 maxLength：历史原文可超 200 字，截断会静默丢字；
            清空后草稿里是 ''，保存时 显式落 private_preferences: ''（不再回落服务端历史文本）。 */}
        <section className={样式.筛选要求区}>
          <div className={样式.筛选要求标}>
            <label className={样式.筛选要求题} htmlFor="候选私有筛选要求">给 AI 代理的筛选要求</label>
            <span className={样式.筛选要求注}>选填</span>
          </div>
          <p className={样式.筛选要求说明} id="候选私有筛选要求说明">写下你的要求和偏好，AI 代理会据此筛选岗位。</p>
          <textarea
            id="候选私有筛选要求"
            aria-describedby="候选私有筛选要求说明"
            className={样式.筛选要求输入}
            value={草稿.私有偏好 ?? ''}
            placeholder=""
            rows={4}
            onChange={(事件) => 改草稿({ 私有偏好: 事件.target.value })}
          />
        </section>
      </滚动区>

      {/* 编辑态底部是「删除 + 保存」两键，新建态只有一个「保存」。
          保存键不再置灰：缺什么点保存时轻提示什么（见 校验必填） */}
      {编辑态 ? (
        <div className={样式.底键行}>
          <button type="button" className={`${样式.删除键} 可点`} onClick={删除}>
            删除
          </button>
          <button type="button" className={`${样式.保存键} 可点`} onClick={提交}>
            保存
          </button>
        </div>
      ) : (
        <主按钮 文字="保存" 按下={提交} 禁用={false} />
      )}

      {/* 毕业年月抽屉（picker 统一 Task 3）：自组弹层/双轮改共用 年月滚轮层；
          确定用一次 改草稿 回填，取消 / 遮罩 / Escape 不调用 */}
      {毕业轮开 && <年月滚轮层
        标题="预计毕业时间"
        初值={毕业初值}
        年份选项={毕业年表}
        最小={`${毕业年表[0]}-01`}
        最大={`${毕业年表[毕业年表.length - 1]}-12`}
        年名称="毕业年"
        月名称="毕业月"
        确认={(值) => {
          改草稿({ 毕业时间: 值 });
          设毕业轮开(false);
        }}
        取消={() => 设毕业轮开(false)}
      />}
      {薪资层开 ? (
        <薪资区间层
          周期={薪资周期}
          下限={草稿.薪资下限}
          上限={草稿.薪资上限}
          确认={(下, 上) => {
            改草稿({ 薪资下限: 下, 薪资上限: 上 });
            设薪资层开(false);
          }}
          取消={() => 设薪资层开(false)}
        />
      ) : null}
      {/* 实习数值抽屉（picker 统一 Task 2）：缺值临时落首档，父字段在确定前仍是
          未填写；取消 / 遮罩 / Escape 只关层，确定才 改草稿 回填那一个字段 */}
      {实习轮 !== null ? (
        <数字滚轮层
          标题={实习轮 === '月数' ? '实习时长' : '每周到岗'}
          初值={实习轮 === '月数'
            ? 草稿.实习月数 ?? 实习月数档[0]
            : 草稿.每周到岗天数 ?? 每周到岗档[0]}
          档位={实习轮 === '月数' ? 实习月数档 : 每周到岗档}
          单位={实习轮 === '月数' ? '个月' : '天'}
          确认={(值) => {
            改草稿(实习轮 === '月数' ? { 实习月数: 值 } : { 每周到岗天数: 值 });
            设实习轮(null);
          }}
          取消={() => 设实习轮(null)}
        />
      ) : null}
    </次级页外壳>
  );
}
